# Rebuild 20-asset manifest and latest Runtime Build ID.
idx=Path('index.html'); text=idx.read_text(); m=re.search(r'const manifest=window\.__wbRuntimeAssetManifest=(\{.*?\});',text,re.S)
if not m: raise SystemExit('manifest missing')
manifest=json.loads(m.group(1)); integrity={}
for name in manifest['assets']:
    integrity[name]='sha256-'+base64.b64encode(hashlib.sha256(Path(name).read_bytes()).digest()).decode()
manifest['integrity']=integrity; canonical='\n'.join(f'{n}:{integrity[n]}' for n in manifest['assets']); old=manifest['buildId']; new='candidate-assets-'+hashlib.sha256(canonical.encode()).hexdigest()[:12]; manifest['buildId']=new
text=text[:m.start(1)]+json.dumps(manifest,separators=(',',':'),ensure_ascii=False)+text[m.end(1):]; text=text.replace(old,new); idx.write_text(text)
latest=Path('latest.json'); obj=json.loads(latest.read_text()); obj['runtimeBuildId']=new; obj['runtimeAssetCount']=len(manifest['assets']); latest.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n'); print('RUNTIME_BUILD_ID='+new)
